import Foundation

struct GuideSection: Identifiable { let id = UUID(); let title: String; let colour: String; let body: String }
struct Release: Identifiable { let id = UUID(); let version: String; let date: String; let items: [String] }

enum Guide {
    static var version: String {
        let v = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "?"
        let b = Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "?"
        return "\(v) (\(b))"
    }

    static let howItWorks: [GuideSection] = [
        GuideSection(title: "What this app is for", colour: "purple", body: "AMS Shortcut Overview helps you learn keyboard shortcuts. It puts one colour card per app on your desktop, along the bottom of the screen, behind all your windows. Each card lists the shortcuts you are still learning. You see them every time you look at the desktop, so they stick. It works on the Mac only, has no Dock icon, and nothing leaves your Mac."),
        GuideSection(title: "The cards on the desktop", colour: "coral", body: "Every app has its own card in its own colour: the app's name at the top, then one row per shortcut. On the left of each row is a small circle, in the middle what the shortcut does, and on the right the keys to press, drawn as little keys. ⌘ is Command, ⌥ is Option, ⌃ is Control and ⇧ is Shift.\n\nA card shows up to 6 shortcuts. If there are more, it says \"+2 more\" at the bottom; the next ones move up as you learn the first. The number of rows can be changed in Settings. The top right of a card says how many of that app's shortcuts you have learned.\n\nA new installation starts with 5 cards: Obsidian, Raycast, Fusion, Finder and Xcode, each with 8 shortcuts. You can add more ready-made apps or remove cards at any time (see \"Ready-made apps\").\n\nThe cards sit at desktop level: windows always cover them. To see them, move your windows aside or show the desktop (for example by clicking the wallpaper, or with a spread of thumb and three fingers on the trackpad)."),
        GuideSection(title: "Ticking a shortcut off", colour: "teal", body: "When you know a shortcut, click its circle. A tick appears, the row is crossed out, and after a moment it disappears from the card. You can also right-click a row and choose \"I know it\".\n\nTwo weeks later the shortcut comes back once, at the top of its card, with a small \"Recheck\" label. If you still know it, tick it again and it is gone for good. If you have forgotten it, right-click it and choose \"Still learning\": it stays on the card as before.\n\nWhen every shortcut of an app is learned, its card disappears from the desktop."),
        GuideSection(title: "Learned this week", colour: "green", body: "A small count shows how many shortcuts you have learned this week, so you can see your progress.\n\n• In the menu of the key icon in the menu bar, a grey line (you cannot click it) says \"Learned this week: 3\" (for example). It sits just above the Version line.\n• At the top of the Learned page in the window, a line says \"This week: 3 learned · 12 learned in all\". The second number is everything that is on the Learned page right now.\n\nWhat counts: a shortcut counts for the week in which you first ticked it as learned. The week starts on Monday (the Swedish calendar) and the count starts again at 0 on the next Monday. It does not matter what happened afterwards: if you tick it again at the recheck, it still counts for its first week. If you press \"Bring back\" (or \"Still learning\"), the learned date is cleared and the shortcut no longer counts.")
,
        GuideSection(title: "Adding and changing shortcuts", colour: "blue", body: "Three ways to add one:\n1. Click the small + at the top right of a card: the new shortcut goes to that app.\n2. Click the key icon in the menu bar and choose \"Add shortcut…\".\n3. In the window, press \"Add shortcut\" at the bottom of the Shortcuts page.\n\nFill in the app, what the shortcut does, and the keys. Type the keys, or press the ⌘ ⌥ ⌃ ⇧ buttons to add a symbol, then type the letter. \"Looks like\" shows how it will look on the card. Save, or Cancel (Escape also cancels).\n\nType a new app name and the app gets a new card with the next free colour. To change or delete a shortcut, right-click it on its card and choose \"Change…\", or press \"Change\" next to it on the Shortcuts page. The Delete button is in the same window."),
        GuideSection(title: "Ready-made apps", colour: "blue", body: "The app carries ready-made lists of 8 checked shortcuts each for 6 apps: Obsidian (purple), Raycast (coral), Fusion (teal), Finder (blue), Xcode (amber) and Safari (green).\n\nWhat is on your desktop:\n• A new installation starts with Obsidian, Raycast, Fusion, Finder and Xcode (5 cards, 40 shortcuts). Safari is not added by itself.\n• If you already used an earlier version, Finder and Xcode are added once, the first time version 0.3 starts, and only if no app of that name is on your list yet. Nothing else in your list changes.\n\nAdd one yourself: on the Shortcuts page press \"Add ready-made app\" at the bottom. A menu lists the ready-made apps that are not on your list yet. Pick one and its card appears with its 8 shortcuts, in its own colour, or in the next free colour if that colour is already taken by another app. When all 6 are on your list, the button is greyed out.\n\nRemove an app: on the Shortcuts page, each app's heading has a \"Remove\" button next to \"Move left\" and \"Move right\". It asks first: \"Remove Finder and its 8 shortcuts?\" with Cancel and Remove. Removing deletes the card and all its shortcuts, including the ones you have learned. You can add a ready-made app again afterwards, but it starts fresh: nothing is marked as learned. As always, the app keeps a safety copy of the previous list.")
,
        GuideSection(title: "The window", colour: "pink", body: "Click the key icon in the menu bar and choose \"Shortcuts and settings…\". The window has five pages:\n• Shortcuts: every shortcut of every app, with its state (empty = still learning, Recheck, Learned). Click the coloured dot next to an app's name to change its colour: every click tries the next of 7 colours; \"Move left\" and \"Move right\" change the order of the cards on the desktop, and \"Remove\" deletes the app and its shortcuts after asking. At the bottom are the buttons \"Add shortcut\" and \"Add ready-made app\" (see \"Ready-made apps\").\n• Learned: a line at the top says \"This week: N learned · M learned in all\"; below it, everything you have learned, with the date of its recheck, or \"Learned for good\". \"Bring back\" puts a shortcut back on its card.\n• Settings: show or hide the cards, shortcuts per card (3 to 12), the two learning switches \"Today's shortcuts\" and \"Quiz me\" (both off until you switch them on), open at login, where your list is kept, and the version.\n• How it works: this guide.\n• What's new: every version, newest first.\n\nThe menu of the keyboard key icon in the menu bar has the same two switches. \"Today's shortcuts\" and \"Quiz me\" each show a tick when they are on, next to \"Show cards on the desktop\". Just above the Version line the menu also has a grey line, \"Learned this week: N\", that you cannot click. Switch them on or off in the menu or in Settings: both places always show the same state, and the cards change straight away."),
        GuideSection(title: "Today's shortcuts", colour: "green", body: "Normally a card shows your shortcuts in the order of your list, so the same ones are always on top. With \"Today's shortcuts\" on, each card shows a fresh pick every day instead.\n\nHow it works:\n• Once a day the order of an app's shortcuts is shuffled. It stays the same all day, and a new order appears after midnight. The app checks the clock every hour and when your Mac wakes up, so the new pick is there when you sit down, even if the Mac slept through midnight.\n• Rechecks still come first, with their \"Recheck\" label, before today's pick.\n• The card shows as many shortcuts as \"Shortcuts per card\" says (3 to 12).\n• When you tick one off, the next of today's pick moves up to fill the place.\n• While the switch is on, the card's header says \"Today\" next to the app's name, so you know you are looking at the day's pick.\n\nThe shuffle is the same for the same day, so closing and opening the app does not change the pick. Only the next day does. Nothing about your list changes: the order on the Shortcuts page stays as you made it, and switching \"Today's shortcuts\" off brings the list order back at once.\n\nSwitch it on in Settings (\"Today's shortcuts\") or in the menu bar icon's menu. It is off by default."),
        GuideSection(title: "Quiz me", colour: "amber", body: "\"Quiz me\" turns the cards into a small test. With it on, the keys on the cards are hidden: each key shows as a blank key cap with a \"?\" on it. You still see how many keys the shortcut takes, but not which ones.\n\nTry to remember the keys first, then look:\n• Point at a row with the mouse, and the real keys appear. Move the mouse away and they hide again.\n• Or click the hidden keys: the real keys stay shown until you click them again. Handy if you want to look in peace.\n\nYou can still tick a shortcut off, right-click it and change it as usual: only the keys are hidden. A good way to use it: say the keys out loud (or press them) before you point at the row, then check.\n\n\"Quiz me\" works together with \"Today's shortcuts\": switch both on and every day you get a new pick to quiz yourself on. Switch it on in Settings (\"Quiz me\") or in the menu bar icon's menu. It is off by default."),
        GuideSection(title: "Your list is safe", colour: "amber", body: "Your shortcuts are kept in a file on this Mac (Settings, \"Show in Finder\"). Before every change the app keeps a safety copy of the previous list next to it. If the list ever cannot be read, the app puts that file aside instead of overwriting it and starts from the safety copy. The first time it starts, the app fills in 8 shortcuts each for Obsidian, Raycast, Fusion, Finder and Xcode. When an older list is updated to 0.3, Finder and Xcode are added to it once and nothing else changes. Removing an app also keeps a safety copy of the list as it was before."),
    ]

    static let releases: [Release] = [
        Release(version: "0.3 (3)", date: "16 Nov 2026", items: [
            "New: \"Learned this week\". The menu of the key icon in the menu bar has a new grey line you cannot click, \"Learned this week: N\", just above the Version line. Before, the menu showed no count of your progress; now it shows how many shortcuts you first ticked as learned since Monday.",
            "Learned this week: the week starts on Monday (Swedish calendar) and starts again at 0 each Monday. A shortcut counts for the week of its first tick, whatever happened afterwards: a later tick at the recheck still counts, and \"Bring back\" removes it from the count because its learned date is cleared.",
            "The Learned page in the window has a new line at the top: \"This week: N learned · M learned in all\". N is the same number as in the menu; M is everything that is on the Learned page right now. Before, the page started straight with the list.",
            "More ready-made apps: the app now carries ready-made lists of 8 checked shortcuts each for 6 apps (before: 3 apps, Obsidian, Raycast and Fusion). New are Finder (blue), Xcode (amber) and Safari (green). Obsidian stays purple, Raycast coral and Fusion teal.",
            "New cards for Finder and Xcode: a fresh installation now starts with 5 cards (before: 3), Obsidian, Raycast, Fusion, Finder and Xcode, 40 shortcuts in all (before: 24). Safari is not added by itself.",
            "If you already used the app, Finder and Xcode are added to your list once, the first time version 0.3 starts, 16 more shortcuts (3 cards become 5). This happens only if no app of that name is on your list yet, and nothing else in your list changes: your shortcuts, ticks, colours and order stay as they are.",
            "New button \"Add ready-made app\" at the bottom of the Shortcuts page, next to \"Add shortcut\". It opens a menu of the ready-made apps that are not on your list yet. Pick one and its card is added with its 8 shortcuts in its own colour, or in the next free colour if that colour is taken. If all 6 are on your list, the button is greyed out. An app whose name is already on the list (in any capitals) is never added twice.",
            "New button \"Remove\" in each app's heading on the Shortcuts page, next to \"Move left\" and \"Move right\". It asks first, for example \"Remove Finder and its 8 shortcuts?\", with Cancel and Remove. Removing deletes the card and all its shortcuts, including the ones you have learned. Before, an app could only be emptied by deleting its shortcuts one by one.",
            "A ready-made app that you removed can be added again; it comes back fresh, with nothing learned. The safety copy of your previous list is kept before every change, as always.",
            "The How it works guide has a new section \"Ready-made apps\" and a new section \"Learned this week\", and the texts about the cards, the window, the menu and \"Your list is safe\" are updated.",
            "Nothing else changed: the learning rules, \"Today's shortcuts\", \"Quiz me\" and your settings work as before.",
        ]),
        Release(version: "0.2 (2)", date: "16 Nov 2026", items: [
            "New: \"Today's shortcuts\". Instead of showing an app's shortcuts in the order of your list, each card shows a fresh pick every day. The order is shuffled once per day: the same all day, a new one after midnight. The app checks the clock every hour and when the Mac wakes up.",
            "Today's shortcuts: rechecks still come first. The card shows as many shortcuts as \"Shortcuts per card\" says; when you tick one off, the next of today's pick moves up. The card's header says \"Today\" next to the app's name. Off by default.",
            "New: \"Quiz me\". The keys on the cards are hidden: each key shows as a blank key cap with a \"?\", so you still see how many keys it takes. Point at a row with the mouse, or click the hidden keys, and the real keys appear. Move away and they hide again; a click keeps them shown until you click again. Try to remember the keys before you look. Off by default.",
            "Both switches, \"Today's shortcuts\" and \"Quiz me\", are in the window's Settings page and in the menu bar icon's menu, where they show a tick when on. The two places always agree.",
            "New app icon and menu bar icon: a keyboard key, drawn in the same hand-drawn style as the icons of the other AMS apps. It replaces the old door key.",
            "The How it works guide has a new section for each of the two new switches, and the Settings description is updated.",
            "Nothing else changed: your list, your colours and the learning rules are as before.",
        ]),
        Release(version: "0.1 (1)", date: "16 Nov 2026", items: [
            "New app. One colour card per app sits on your desktop, along the bottom of the screen, behind your windows: Obsidian in purple, Raycast in coral, Fusion in teal, each starting with 8 shortcuts.",
            "Each row shows what the shortcut does and its keys, drawn as little keys.",
            "Tick a shortcut's circle when you know it: it is crossed out and disappears. Two weeks later it comes back once with a \"Recheck\" label; tick it again and it is gone for good, or choose \"Still learning\" to keep it.",
            "A card shows up to 6 shortcuts and \"+N more\"; it shows how many you have learned, and it disappears when all are learned.",
            "Add shortcuts with the + on a card, from the key icon in the menu bar, or in the window. A new app name gets a new card with the next free colour.",
            "Change or delete a shortcut by right-clicking it on its card, or in the window.",
            "The window has five pages: Shortcuts, Learned (with \"Bring back\"), Settings, How it works and What's new.",
            "Settings: show or hide the cards, shortcuts per card (3 to 12), open at login, where your list is kept, version number.",
            "Change an app's colour and the order of the cards.",
            "Your list stays on this Mac, with a safety copy before every change.",
            "Day and night colours for every card.",
        ]),
    ]
}
